import React, { useState } from "react";
import "./Dashboard.css";

function Dashboard() {
  const [file, setFile] = useState(null);
  const [transactions, setTransactions] = useState([]);
  const [type, setType] = useState("");
  const [darkMode, setDarkMode] = useState(false);
  const [activeTab, setActiveTab] = useState("overview");
  const [loading, setLoading] = useState(false);

  // 🔥 SMART SOURCE DETECTION FALLBACK
  const detectSourceFromTransactions = (txns) => {
    const text = txns.map(t => t.description || "").join(" ").toLowerCase();

    if (text.includes("gpay") || text.includes("google pay")) return "GPay";
    if (text.includes("phonepe")) return "PhonePe";
    if (text.includes("paytm")) return "Paytm";
    if (text.includes("upi")) return "UPI";

    return "Unknown";
  };

  const handleUpload = async () => {
    if (!file) return alert("Please select a PDF file");

    const formData = new FormData();
    formData.append("file", file);

    try {
      setLoading(true);

      const res = await fetch("http://localhost:8000/upload-statement/", {
        method: "POST",
        body: formData,
      });

      const data = await res.json();

      const txns = data.transactions || data || [];

      const finalTransactions = Array.isArray(txns) ? txns : [];

      setTransactions(finalTransactions);

      // 🔥 FIXED SOURCE DETECTION
      const detectedSource =
        data.detected_type ||
        data.source ||
        data.bank ||
        detectSourceFromTransactions(finalTransactions);

      setType(detectedSource);

      // SAVE HISTORY
      const history = JSON.parse(localStorage.getItem("history")) || [];

      history.unshift({
        date: new Date().toLocaleString(),
        type: detectedSource,
        count: finalTransactions.length
      });

      localStorage.setItem("history", JSON.stringify(history));

    } catch (err) {
      console.error(err);
      alert("Error processing file");
    } finally {
      setLoading(false);
    }
  };

  return (
    <div className={`dashboard-main ${darkMode ? "dark" : ""}`}>
      <div className="container">

        {/* LOADER */}
        {loading && (
          <div style={{
            position: "fixed",
            top: 0,
            left: 0,
            width: "100%",
            height: "100%",
            background: "rgba(15, 23, 42, 0.6)",
            backdropFilter: "blur(6px)",
            display: "flex",
            alignItems: "center",
            justifyContent: "center",
            zIndex: 999
          }}>
            <div style={{
              background: "rgba(255,255,255,0.9)",
              padding: "30px 40px",
              borderRadius: "16px",
              textAlign: "center",
              boxShadow: "0 10px 40px rgba(0,0,0,0.2)"
            }}>
              <h3>Analyzing Statement...</h3>
              <p>Please wait while we process your file</p>
            </div>
          </div>
        )}

        {/* NAVBAR */}
        <div className="navbar">
          <div className="logo">FinSight</div>

          <div className="nav-actions">
            <div className="tabs">
              <span
                className={`tab ${activeTab === "overview" ? "active-tab" : ""}`}
                onClick={() => setActiveTab("overview")}
              >
                Overview
              </span>

              <span
                className={`tab ${activeTab === "transactions" ? "active-tab" : ""}`}
                onClick={() => setActiveTab("transactions")}
              >
                History
              </span>
            </div>

            <div
              className={`theme-circle ${darkMode ? "dark" : "light"}`}
              onClick={() => setDarkMode(!darkMode)}
            ></div>
          </div>
        </div>

        {/* HERO */}
        <div className="hero">
          <h1>Personal Expense Intelligence</h1>
          <p>AI-powered financial insights from your statements</p>
        </div>

        {/* KPI */}
        <div className="kpi-grid">
          <div className="kpi-card">
            <h4>Statement Source</h4>
            <p>{type || "Not uploaded"}</p>
          </div>

          <div className="kpi-card">
            <h4>Total Transactions</h4>
            <p>{transactions.length}</p>
          </div>

          <div className="kpi-card">
            <h4>Status</h4>
            <p>{transactions.length ? "Processed" : "Waiting"}</p>
          </div>
        </div>

        {/* OVERVIEW */}
        {activeTab === "overview" && (
          <>
            <div className="top-section">
              <div className="card upload-card">
                <h3>Upload Statement</h3>

                <div className="upload-row">
                  <input
                    type="file"
                    accept=".pdf"
                    onChange={(e) => setFile(e.target.files[0])}
                  />
                  <button onClick={handleUpload}>
                    Analyze Statement
                  </button>
                </div>
              </div>

              <div className="card summary-card">
                <h3>Insights Summary</h3>
                <p>
                  We extract transactions and detect spending behavior automatically.
                </p>
              </div>
            </div>

            {transactions.length > 0 && (
              <div className="card table-card">
                <h3>Transaction Ledger</h3>

                <div className="table-wrapper">
                  <table>
                    <thead>
                      <tr>
                        <th>Date</th>
                        <th>Type</th>
                        <th>Description</th>
                        <th>Amount</th>
                        <th>Category</th>
                        <th>Need/Want</th>
                      </tr>
                    </thead>

                    <tbody>
                      {transactions.map((txn, i) => (
                        <tr key={i}>
                          <td>{txn.date || "-"}</td>
                          <td className={txn.type === "debit" ? "debit" : "credit"}>
                            {txn.type}
                          </td>
                          <td>{txn.description}</td>
                          <td>₹{txn.amount}</td>
                          <td>{txn.category || "Other"}</td>
                          <td>{txn.classification || txn.need_want || "Other"}</td>
                        </tr>
                      ))}
                    </tbody>
                  </table>
                </div>
              </div>
            )}
          </>
        )}

        {/* HISTORY */}
        {activeTab === "transactions" && (
          <div className="card table-card">
            <h3>Upload History</h3>

            <div className="table-wrapper">
              <table>
                <thead>
                  <tr>
                    <th>Date</th>
                    <th>Source</th>
                    <th>Transactions</th>
                  </tr>
                </thead>

                <tbody>
                  {(JSON.parse(localStorage.getItem("history")) || []).map((h, i) => (
                    <tr key={i}>
                      <td>{h.date}</td>
                      <td>{h.type}</td>
                      <td>{h.count}</td>
                    </tr>
                  ))}
                </tbody>
              </table>
            </div>
          </div>
        )}

      </div>
    </div>
  );
}

